/**
 * wowacool Worker.
 *
 * GET / is the Chinese operations workbench. GET /health stays JSON for ops checks.
 * Jobs, copy, images, review, and export run in the request against D1 and R2.
 * Copy and topic ideas use OpenRouter free text models only.
 * Still images use the Workers AI binding when IMAGE_PROVIDER=workers_ai.
 * This module does not generate or publish video.
 * This module does not publish to Xiaohongshu and does not scrape.
 *
 * `Env` comes from `worker-configuration.d.ts`, generated by `wrangler types`.
 */
import { PROJECT_NAME } from "../constants.js";
import { assertUnlocked, login, logout, sessionStatus } from "./auth.js";
import {
  catalogResponse,
  createJobResponse,
  deleteImageResponse,
  draftResponse,
  topicsResponse,
  duplicateResponse,
  exportResponse,
  generateImagesResponse,
  getJobResponse,
  imageResponse,
  listJobsResponse,
  packageResponse,
  patchJobResponse,
  quotaResponse,
  describeImages,
  refreshCatalogResponse,
  reorderResponse,
  reviewResponse,
  uploadImagesResponse,
} from "./handlers.js";
import { assertId, errorResponse, json } from "./http.js";
import { renderApp } from "./ui.js";

const PUBLIC = new Set(["health", "home", "favicon", "session", "login", "logout"]);

const TABLE: Array<{ method: string; pattern: string; name: string }> = [
  { method: "GET", pattern: "/health", name: "health" },
  { method: "GET", pattern: "/", name: "home" },
  { method: "GET", pattern: "/favicon.svg", name: "favicon" },
  { method: "GET", pattern: "/session", name: "session" },
  { method: "POST", pattern: "/session", name: "login" },
  { method: "DELETE", pattern: "/session", name: "logout" },
  { method: "GET", pattern: "/quota", name: "quota" },
  { method: "GET", pattern: "/catalog", name: "catalog" },
  { method: "POST", pattern: "/catalog/refresh", name: "catalogRefresh" },
  { method: "POST", pattern: "/topics", name: "topics" },
  { method: "GET", pattern: "/jobs", name: "list" },
  { method: "POST", pattern: "/jobs", name: "create" },
  { method: "POST", pattern: "/jobs/:id/draft", name: "draft" },
  { method: "POST", pattern: "/jobs/:id/images/upload", name: "upload" },
  { method: "POST", pattern: "/jobs/:id/images/reorder", name: "reorder" },
  { method: "POST", pattern: "/jobs/:id/images", name: "images" },
  { method: "DELETE", pattern: "/jobs/:id/images/:assetId", name: "deleteImage" },
  { method: "GET", pattern: "/jobs/:id/images/:assetId", name: "image" },
  { method: "POST", pattern: "/jobs/:id/review", name: "review" },
  { method: "POST", pattern: "/jobs/:id/export", name: "export" },
  { method: "GET", pattern: "/jobs/:id/package", name: "package" },
  { method: "POST", pattern: "/jobs/:id/duplicate", name: "duplicate" },
  { method: "PATCH", pattern: "/jobs/:id", name: "patch" },
  { method: "GET", pattern: "/jobs/:id", name: "get" },
];

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const started = Date.now();
    const url = new URL(request.url);
    try {
      const response = await route(request, env, url);
      console.log(
        JSON.stringify({
          message: "request",
          method: request.method,
          path: url.pathname,
          status: response.status,
          ms: Date.now() - started,
        }),
      );
      return response;
    } catch (error) {
      const response = errorResponse(error);
      console.error(
        JSON.stringify({
          message: "request failed",
          method: request.method,
          path: url.pathname,
          status: response.status,
          ms: Date.now() - started,
        }),
      );
      return response;
    }
  },
} satisfies ExportedHandler<Env>;

async function route(request: Request, env: Env, url: URL): Promise<Response> {
  const hit = match(request.method, url.pathname);
  if (!hit) return json({ ok: false, error: "没有这个页面", code: "not_found" }, 404);
  if (!PUBLIC.has(hit.name)) await assertUnlocked(request, env);
  const id = hit.params.id ? assertId(hit.params.id, "任务") : "";
  const assetId = hit.params.assetId ? assertId(hit.params.assetId, "图片") : "";

  switch (hit.name) {
    case "health":
      return health(env);
    case "home":
      return html(renderApp());
    case "favicon":
      return favicon();
    case "session":
      return sessionStatus(request, env);
    case "login":
      return login(request, env);
    case "logout":
      return logout(request);
    case "quota":
      return quotaResponse(env);
    case "catalog":
      return catalogResponse(env);
    case "catalogRefresh":
      return refreshCatalogResponse(env);
    case "topics":
      return topicsResponse(request, env);
    case "list":
      return listJobsResponse(request, env);
    case "create":
      return createJobResponse(request, env);
    case "get":
      return getJobResponse(request, env, id);
    case "patch":
      return patchJobResponse(request, env, id);
    case "draft":
      return draftResponse(request, env, id);
    case "images":
      return generateImagesResponse(request, env, id);
    case "upload":
      return uploadImagesResponse(request, env, id);
    case "reorder":
      return reorderResponse(request, env, id);
    case "deleteImage":
      return deleteImageResponse(env, id, assetId, request);
    case "image":
      return imageResponse(env, id, assetId);
    case "review":
      return reviewResponse(request, env, id);
    case "export":
      return exportResponse(request, env, id);
    case "package":
      return packageResponse(env, id);
    case "duplicate":
      return duplicateResponse(request, env, id);
    default:
      return json({ ok: false, error: "没有这个页面", code: "not_found" }, 404);
  }
}

function health(env: Env): Response {
  const image = describeImages(env);
  return json({
    ok: true,
    service: PROJECT_NAME,
    phase: env.PHASE ?? "2",
    mode: "health",
    imageProvider: image.provider,
    imageReady: image.ready,
    imageModel: image.model,
    imageSize: image.size,
    imageMessage: image.message,
    copy: "openrouter-free-text-only",
    writeNotes: "planned",
    humanReviewRequired: true,
    app: "/",
  });
}

function html(body: string): Response {
  return new Response(body, {
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-store",
      "x-content-type-options": "nosniff",
      "referrer-policy": "no-referrer",
      "content-security-policy":
        "default-src 'self'; img-src 'self' data: blob:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",
    },
  });
}

function favicon(): Response {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#ff2442"/><text x="32" y="44" text-anchor="middle" font-size="34" font-family="Georgia,serif" fill="#fff">图</text></svg>`;
  return new Response(svg, {
    headers: { "content-type": "image/svg+xml", "cache-control": "public, max-age=86400" },
  });
}

function match(method: string, pathname: string): { name: string; params: Record<string, string> } | null {
  const path = pathname.length > 1 ? pathname.replace(/\/+$/, "") : pathname;
  const parts = path.split("/").filter(Boolean);
  for (const route of TABLE) {
    if (route.method !== method) continue;
    const bits = route.pattern.split("/").filter(Boolean);
    if (route.pattern === "/" && parts.length === 0) return { name: route.name, params: {} };
    if (bits.length !== parts.length) continue;
    const params: Record<string, string> = {};
    let ok = true;
    for (let i = 0; i < bits.length; i += 1) {
      if (bits[i].startsWith(":")) params[bits[i].slice(1)] = parts[i];
      else if (bits[i] !== parts[i]) {
        ok = false;
        break;
      }
    }
    if (ok) return { name: route.name, params };
  }
  return null;
}
